        Quest("source_compare", "Два источника", "mind", "Сравни 2 источника по одному вопросу в таблице: совпадения, различия, вывод. Укажи названия источников.", 35, 3, 0, 0, 0),
        Quest("math_practice", "Три задачи без подсказки", "mind", "Реши 3 задачи по изучаемой теме без готовых ответов. Затем проверь и распиши одну ошибку.", 30, 1, 0, 0, 0),
