        Quest("request_clear", "Ясная просьба", "social", "Сформулируй одну просьбу: действие, срок и почему это важно. Оставь человеку возможность отказать.", 20, 2, 0, 0, 0),
        Quest("apology", "Извинение без оправданий", "social", "Если есть реальный повод, назови поступок, признай влияние и предложи исправление. Не добавляй «но ты».", 30, 3, 0, 0, 0),
