        Quest("conflict_pause", "Пауза в споре", "social", "В напряжённом разговоре предложи паузу 10 минут и назови время возвращения. После сформулируй общую цель.", 30, 4, 0, 0, 0),
        Quest("boundary_time", "Защитить своё время", "social", "Ответь на одну просьбу реальными возможностями: что можешь, когда и в каком объёме. Не обещай невозможного.", 25, 2, 0, 0, 0),
        Quest("invite_event", "Конкретное приглашение", "social", "Предложи человеку встречу с точным занятием, датой и длительностью. Примини ответ без давления.", 20, 1, 0, 0, 0),
