        Quest("price_unit", "Цена за единицу", "finance", "Сравни 3 похожих товара по цене за единицу объёма или веса. Запиши расчёт и выбранный вариант.", 20, 1, 0, 0, 0),
        Quest("bill_calendar", "Календарь счетов", "finance", "Добавь 3 ближайших обязательных платежа в календарь с напоминанием за 2 дня. Проверь суммы.", 25, 2, 0, 0, 0),
